<?php declare(strict_types=1); ?>
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ev sahipleri</title><style>body{font-family:system-ui;background:#f5f7f5;color:#26332b;margin:0}.wrap{max-width:1050px;margin:35px auto;padding:0 18px}table{width:100%;border-collapse:collapse;background:white;border-radius:13px;overflow:hidden}td,th{text-align:left;padding:14px;border-bottom:1px solid #edf0ed;font-size:14px}button{border:0;background:#176b50;color:white;padding:9px 12px;border-radius:8px;font-weight:700}.tag{background:#eef4ef;padding:5px 8px;border-radius:15px}</style></head><body><main class="wrap"><h1>Ev sahibi başvuruları</h1><table><thead><tr><th>İşletme</th><th>Hesap</th><th>Telefon</th><th>Durum</th><th>İşlem</th></tr></thead><tbody><?php foreach($vendors as $v): ?><tr><td><?= e($v['business_name']) ?></td><td><?= e($v['username']) ?><br><?= e($v['email']) ?></td><td><?= e($v['phone']) ?></td><td><span class="tag"><?= e($v['status']) ?></span></td><td><?php if($v['status']!=='approved'): ?><form method="post" action="/admin/vendors/approve"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$v['id'] ?>"><button type="submit">Onayla</button></form><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$vendors): ?><tr><td colspan="5">Başvuru bulunmuyor.</td></tr><?php endif; ?></tbody></table><p><a href="/admin">Yönetim paneli</a></p></main></body></html>